    function deepGet(obj, path, defaultValue = "N/A") {
        if (!path || typeof path !== 'string') return defaultValue;
        const value = path.split('.').reduce((p, c) => (p && p[c] !== undefined) ? p[c] : undefined, obj);
        return value !== undefined && value !== null ? (Array.isArray(value) ? value[0] : value) : defaultValue;
    }

    function updateSarcomaProgressBar(barId, rawValue) {
        const barElement = document.getElementById(barId);
        if (!barElement) return;
        const percentage = Math.max(0, Math.min(100, (parseFloat(rawValue) || 0)));
        barElement.style.width = `${percentage}%`;
    }

   function updateAffectionProgressBar(barId, valueId, heartId, rawValue) {
        const bar = document.getElementById(barId), val = document.getElementById(valueId), heart = document.getElementById(heartId);
        if (!bar || !val || !heart) return;
        val.innerText = String(rawValue).split('(')[0].trim();
        let numVal = parseFloat(String(rawValue));
        if(isNaN(numVal)) numVal = 0;
        const ranges = { neg: 30, pos1: 60, pos2: 10 };
        let totalPercent = 0;
        if (numVal < 0) totalPercent = ((numVal + 100) / 100) * ranges.neg;
        else if (numVal <= 200) totalPercent = ranges.neg + (numVal / 200) * ranges.pos1;
        else totalPercent = ranges.neg + ranges.pos1 + ((numVal - 200) / 1800) * ranges.pos2;
        totalPercent = Math.max(0, Math.min(100, totalPercent));
        bar.style.width = `${totalPercent}%`;
        bar.style.opacity = numVal < 0 ? '0' : '1';
        heart.style.left = `calc(${totalPercent}% - 9px)`;
    }

    function toggleSection(header) {
        const content = header.nextElementSibling;
        const arrow = header.querySelector('span:last-child');
        content.classList.toggle('expanded');
        arrow.textContent = content.classList.contains('expanded') ? '▼' : '▲';
    }

    function updateDisplayWithDataSource() {
        document.querySelectorAll('.property, .section').forEach(el => el.classList.add('hidden'));

        const paths = {
            '世界.日期': 'world-date', '世界.时间': 'world-time', '世界.地点': 'world-location',
            '禾青苗.身体状态.胸部': 'heqingmiao-chest', '禾青苗.身体状态.阴蒂': 'heqingmiao-clitoris',
            '禾青苗.身体状态.阴道': 'heqingmiao-vagina', '禾青苗.身体状态.宫颈': 'heqingmiao-cervix',
            '禾青苗.身体状态.子宫': 'heqingmiao-uterus', '禾青苗.身体状态.菊穴': 'heqingmiao-anus',
            '禾青苗.好感度': 'heqingmiao-affection',
            '禾青苗.健康状态.骨肉瘤恶化程度': 'heqingmiao-sarcoma-level'
        };

        for (const path in paths) {
            const value = deepGet(current_data_source, path);
            if (value !== 'N/A') {
                const elementId = paths[path];
                const element = document.getElementById(elementId);
                const propertyDiv = element ? element.closest('.property') : document.querySelector(`[data-key="${path}"]`);
                if (propertyDiv) {
                    propertyDiv.classList.remove('hidden');
                    propertyDiv.closest('.section').classList.remove('hidden');
                    if (path === '禾青苗.好感度') {
                        updateAffectionProgressBar('heqingmiao-affection-bar', 'heqingmiao-affection', 'heqingmiao-affection-heart', value);
                    } else if (path === '禾青苗.健康状态.骨肉瘤恶化程度') {
                        updateSarcomaProgressBar('heqingmiao-sarcoma-level-bar', value);
                    } else if (element) {
                        element.innerText = value;
                    }
                }
            }
        }
    }

    function updateDataSource() {
        const showDelta = document.getElementById('data-toggle').checked;
        const label = document.getElementById('toggle-label-text');
        current_data_source = (showDelta && gameData.delta_data) ? gameData.delta_data : gameData.stat_data;
        label.innerText = (showDelta && gameData.delta_data) ? '仅显示变更' : '显示全部';
        updateDisplayWithDataSource();
    }

    async function init() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            const data = messages?.[0]?.data;
            if (!data) return;
            gameData.stat_data = data.stat_data || {};
            gameData.delta_data = data.delta_data || null;

            const toggle = document.getElementById('data-toggle');
            toggle.disabled = !gameData.delta_data;
            toggle.checked = localStorage.getItem('heqingmiao_showDelta') === 'true' && !toggle.disabled;

            document.querySelectorAll('.section-header').forEach(toggleSection);
            updateDataSource();
            toggle.addEventListener('change', () => {
                localStorage.setItem('heqingmiao_showDelta', toggle.checked);
                updateDataSource();
            });
        } catch(e) { console.error("状态栏初始化失败", e); }
    }

    document.addEventListener('DOMContentLoaded', () => {
        if (typeof getChatMessages === 'function') init();
        else {
            console.log("非SillyTavern环境，使用测试数据");
            gameData = {
                stat_data: {"世界":{"日期":"2024年9月3日","时间":"10:00 白天","地点":"医院"},"禾青苗":{"好感度":160,"健康状态":{"骨肉瘤恶化程度":40},"身体状态":{"胸部":"...","阴蒂":"...","阴道":"...","宫颈":"...","子宫":"...","菊穴":"..."}}},
                delta_data: {"世界":{"时间":"10:00 白天 -> 11:30 白天"},"禾青苗":{"好感度":"160 -> 175"}}
            };
            init();
        }
    });

</script>
